using System;
namespace UnityEngine {public static class Mathf {public static float Min(params float[] xs){float r=xs[0];foreach(float x in xs)if(x<r)r=x;return r;}public static float Max(float a,float b){return a>b?a:b;}public static float Clamp01(float x){return x<0?0:x>1?1:x;}}}
class Check {static void Assert(bool ok,string msg){if(!ok)throw new Exception(msg);}static void Main(){int checks=0;float[] v={-1,0,0.01f,0.5f,0.51f,1,79.49f,79.5f,80,100,125,1000,float.MaxValue};
foreach(float sip in v)foreach(float left in v)foreach(float free in v)foreach(float useful in v){var plan=RebirthConsumptionServing.Drink(sip,left,free,useful);float amount=UnityEngine.Mathf.Min(sip,left,free,useful);bool accepted=free>0.5f&&amount>0.5f;Assert(plan.Accepted==accepted,"drink acceptance changed");if(accepted){Assert(plan.ConsumedMl==amount,"drink amount changed");Assert(plan.StomachLimited==(free+0.5f<UnityEngine.Mathf.Min(sip,left,useful)),"drink fullness changed");}checks++;}
foreach(float solid in v)foreach(float water in v)foreach(float free in v)foreach(float fraction in new[]{-1f,0,0.8f,1,2}){float occupied=UnityEngine.Mathf.Max(0,solid)+UnityEngine.Mathf.Max(0,water);bool accept=!(occupied>0.5f&&free+0.5f<occupied*UnityEngine.Mathf.Clamp01(fraction));var plan=RebirthConsumptionServing.Food(solid,water,free,fraction);Assert(plan.Accepted==accept,"food acceptance changed");if(accept)Assert(plan.OverfillsStomach==(occupied>free+0.5f),"food overfill changed");checks++;}
Assert(!RebirthConsumptionServing.Drink(125,100,0.5f,float.MaxValue).Accepted,"full stomach drank");Assert(RebirthConsumptionServing.Drink(125,100,20,float.MaxValue).ConsumedMl==20,"partial sip");Assert(RebirthConsumptionServing.Food(100,0,79.5f,0.8f).Accepted&&!RebirthConsumptionServing.Food(100,0,79.49f,0.8f).Accepted,"food tolerance");Console.WriteLine("PASS: "+checks+" serving decisions match prior finite-input rules; full stomach, partial sip and food tolerance boundaries.");}}
